"""Run a case generated by CICE-JAX cice.setup."""

import argparse
import json
import os
import sys
import traceback
from contextlib import redirect_stdout
from datetime import datetime
from pathlib import Path

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--profile", action="store_true", help="Capture GPU steps 5-10.")
parser.add_argument("--warmup-steps", type=int, default=7,
                    help="Advance this many real steps before timing the remaining loop (default: 7).")
parser.add_argument("--disable-cuda-command-buffer", action="store_true",
                    help="Compatibility fallback; disable CUDA command buffers globally.")
args = parser.parse_args()
if args.warmup_steps < 1:
    parser.error("--warmup-steps must be a positive integer")

CASE = Path(__file__).resolve().parent
config_path = CASE / "case.json"
if not config_path.is_file():
    parser.error("case.json is missing; run cice.setup first, then execute the generated run.py")
config = json.loads(config_path.read_text(encoding="utf-8"))
source = (CASE / config["source"]).resolve()
if not (source / "cicecore").is_dir() or not (source / "icepack").is_dir():
    parser.error(f"CICE-JAX source not found at {source}; check case.json source path")
sys.path.insert(0, str(source))

# Set before backend initialization; a server run must not silently use CPU.
os.environ["JAX_PLATFORMS"] = "cuda"
DISABLE_CUDA_COMMAND_BUFFER = args.disable_cuda_command_buffer
if DISABLE_CUDA_COMMAND_BUFFER:
    os.environ["XLA_FLAGS"] = (
        os.environ.get("XLA_FLAGS", "") + " --xla_gpu_enable_command_buffer="
    ).strip()

import jax
import jaxlib

jax.config.update("jax_enable_x64", True)

PROFILE_GPU = args.profile
PROFILE_STEPS = (5, 10)
DETAILED_PHYSICS_STEPS = tuple(range(1, 8))  # None restores per-stage synchronization on every step.
PROFILE_PICARD = False
PICARD_BATCH_STOP = True
CLEANUP_CATEGORY_UNROLL = 5
REBIN_STATIC_TRACERS = True
THERM2_BATCH_JIT = True
RIDGE_BATCH_JIT = True
RIDGE_BATCH_STOP = True

from cicecore.cicedyn.general import ice_init, ice_step_mod
from cicecore.cicedyn.infrastructure import ice_domain
from cicecore.drivers.standalone.cice.CICE import icemodel
from cicecore.shared import ice_calendar, ice_fileunits, ice_init_column
from icepack.columnphysics import icepack_itd

os.chdir(CASE)
Path("history").mkdir(exist_ok=True)
Path("restart").mkdir(exist_ok=True)
log_path = CASE / f"cice.runlog.{datetime.now():%Y%m%d-%H%M%S-%f}"
profile_dir = Path("profiles") / log_path.name if PROFILE_GPU else None

# The model calls these readers without arguments.
ice_init.input_data.__defaults__ = ("ice_in",)
ice_init_column.input_zbgc.__defaults__ = ("ice_in",)
ice_domain.init_domain_blocks.__defaults__ = ("ice_in",)
ice_step_mod.DEBUG_REPLAY_ATMO_COEFFICIENTS = False
ice_step_mod.DEBUG_REPLAY_ATMO_PSI = False
ice_step_mod.DEBUG_REPLAY_ATMO_MATH = False
ice_step_mod.PROFILE_PICARD_STEPS = PROFILE_STEPS if PROFILE_PICARD else None
ice_step_mod.PICARD_BATCH_STOP = PICARD_BATCH_STOP
ice_step_mod.THERM2_BATCH_JIT = THERM2_BATCH_JIT
ice_step_mod.RIDGE_BATCH_JIT = RIDGE_BATCH_JIT
ice_step_mod.RIDGE_BATCH_STOP = RIDGE_BATCH_STOP
icepack_itd.CLEANUP_CATEGORY_UNROLL = CLEANUP_CATEGORY_UNROLL
icepack_itd.REBIN_STATIC_TRACERS = REBIN_STATIC_TRACERS

print(f"Running {CASE.name}; log: {log_path}", flush=True)
if profile_dir is not None:
    print(f"GPU profile steps {PROFILE_STEPS}: {profile_dir}", flush=True)
with log_path.open("w", encoding="utf-8") as log:
    try:
        with redirect_stdout(log):
            ice_fileunits.nu_diag = log
            print("Configuration:", config["configuration"])
            print("Case:", CASE, "source:", source)
            print("Python:", sys.version, "JAX:", jax.__version__, "jaxlib:", jaxlib.__version__)
            print("Backend:", jax.default_backend(), "devices:", jax.devices())
            print("JAX x64:", jax.config.x64_enabled)
            print("Picard iteration statistics:", ice_step_mod.PROFILE_PICARD_STEPS)
            print("Picard batch convergence guard:", PICARD_BATCH_STOP,
                  "schedule=4+12x8" if PICARD_BATCH_STOP else "schedule=100")
            print("Detailed physics timing steps:", DETAILED_PHYSICS_STEPS)
            print("Loop timing warmup steps:", args.warmup_steps)
            print("Cleanup category loop unroll:", CLEANUP_CATEGORY_UNROLL)
            print("Rebin static tracer recovery:", REBIN_STATIC_TRACERS)
            print("Therm2 whole-column batch JIT:", THERM2_BATCH_JIT)
            print("Ridge whole-column batch JIT:", RIDGE_BATCH_JIT)
            print("Ridge batch convergence guard:", RIDGE_BATCH_JIT and RIDGE_BATCH_STOP)
            print("CUDA command buffer disabled by runner:", DISABLE_CUDA_COMMAND_BUFFER)
            print("Shortwave radiation command buffer: disabled locally for CUDA replay compatibility")
            for name in ("JAX_ENABLE_X64", "JAX_PLATFORMS", "XLA_FLAGS",
                         "CUDA_VISIBLE_DEVICES", "NVIDIA_TF32_OVERRIDE"):
                print(f"{name}={os.environ.get(name, '<unset>')}")
            print("Input namelist:\n" + Path("ice_in").read_text(encoding="utf-8"), flush=True)
            icemodel(profile_dir=profile_dir, profile_steps=PROFILE_STEPS,
                     detailed_physics_steps=DETAILED_PHYSICS_STEPS,
                     warmup_steps=args.warmup_steps)
            jax.effects_barrier()
            print(f"Final calendar: istep1={ice_calendar.istep1}, npt={ice_calendar.npt}", flush=True)
    except BaseException:
        traceback.print_exc(file=log)
        raise
print(f"Completed {CASE.name}", flush=True)
